hooks.command:
for f in $(git diff --cached --name-only 2>/dev/null); do
  case "$f" in
    *.rs) command -v rustfmt >/dev/null 2>&1 && rustfmt "$f" 2>/dev/null || true ;;
    *.ts|*.tsx|*.js|*.jsx|*.json) command -v npx >/dev/null 2>&1 && npx prettier --write "$f" 2>/dev/null || true ;;
  esac
done

INPUT=$(cat)
CMD=$(printf '%s' "$INPUT" | jq -r '.tool_input.command // empty' 2>/dev/null || printf '%s' "$INPUT")
printf '%s' "$CMD" | grep -qE 'git commit' || exit 0

echo "🔍 Running pre-commit checks..."

if [ -f "Anchor.toml" ] || grep -q "solana-program" Cargo.toml 2>/dev/null; then
  cargo fmt --check || { cargo fmt; echo "❌ rustfmt reformatted files — review and re-run the commit" >&2; exit 2; }
  cargo clippy --all-targets -- -D warnings || { echo "❌ cargo clippy failed" >&2; exit 2; }
  cargo test --lib || { echo "❌ cargo test --lib failed" >&2; exit 2; }
fi

if [ -f "package.json" ]; then
  npx prettier --check "**/*.{ts,tsx,js,jsx,json}" || { npx prettier --write "**/*.{ts,tsx,js,jsx,json}"; echo "❌ prettier reformatted files — review and re-run the commit" >&2; exit 2; }
  if [ -f "tsconfig.json" ]; then
    npx tsc --noEmit || { echo "❌ tsc --noEmit failed" >&2; exit 2; }
  fi
fi

echo "✅ Pre-commit checks passed"
